import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        int e = Integer.parseInt(reader.readLine().trim());
        int s = Integer.parseInt(reader.readLine().trim());
        int l = Integer.parseInt(reader.readLine().trim());

        int maxPos = Math.max(e, Math.max(s, l));
        int minPos = Math.min(e, Math.min(s, l));

        int totalDistance = 2 * (maxPos - minPos);

        System.out.println(totalDistance);
    }
}
